"""Write the review companion from the current run's evidence register."""
from pathlib import Path
from html import escape as e
import json
root=Path(__file__).resolve().parents[1]
ledger=json.loads((root/'working/evidence-ledger.json').read_text())
rows=''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in [i['id'],i['topic'],i['treatment'],i['request'],i['owner_role']])+'</tr>' for i in ledger['issues'])
sources=''.join('<li>'+e(s['path'])+'</li>' for s in ledger['sources'])
out=root/'outputs';out.mkdir(exist_ok=True)
(out/'review-notes.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northbridge 复核说明</title><style>body{font-family:Arial,"PingFang SC",sans-serif;max-width:1150px;margin:48px auto;padding:0 24px;color:#000;line-height:1.7}h1,h2,a{color:#00338d}table{border-collapse:collapse;width:100%}th,td{padding:12px;border:1px solid #b8c7df;text-align:left;vertical-align:top}th{background:#00338d;color:white}tr:nth-child(odd) td{background:#dbe8f8}</style><h1>Northbridge 资料与复核说明</h1><p>本案例全部公司、人物和数据均为虚构。新增材料的模拟提交日期为 2026 年 1 月 26 日。</p><p><a href="northbridge-im.html">打开完整 10 页 HTML</a> · <a href="northbridge-im-editable.pptx">下载可编辑 PPT</a></p><h2>资料范围</h2><p>''' + f'{len(ledger["sources"])} 份输入、{len(ledger["facts"])} 条事实记录、{len(ledger["calculations"])} 项计算。前四份保留原始口径，05–13 补充商业、运营、财务和交易资料。' + '''</p><ul>'''+sources+'''</ul><h2>重要口径</h2><p>FY2025 收入仍采用模型 £25.0m，旧简介的 £26.2m 差异未解决。季度、区域、行业和服务明细的加总相符只说明内部一致，不能证明财务已审计。新增合同续约率为 23/25 = 92%，保留合同金额为 3.72/4.00 = 93%，均不等于旧访谈中未定义的 94% 客户留存率。</p><p>新增预测桥接为集团层面假设，管线全部未签约。现金、银行借款和贸易营运资金仅为有限草稿，不能直接作为交易净债务或标准化营运资金。</p><h2>未决问题与处理</h2><table><tr><th>ID</th><th>主题</th><th>当前处理</th><th>需要的证据</th><th>负责人</th></tr>'''+rows+'''</table><h2>设计及使用限制</h2><p>本版按三页样张的 KPMG 报告参考风格制作，Arial 替代专用字体。尚未使用正式 PPTX 母版。仓库不包含原始报告、截图、Logo 或专用字体。PPT 文字、14 个表格和 2 个图表均为原生对象，图表附数据快照工作簿。HTML 与 PPT 不会自动双向同步。</p><p>本轮 HTML 和原生 PPT 由同一份故事板生成，未通过浏览器读取 HTML DOM。本轮 HTML 未进行浏览器视觉或交互复测。检查程序及已保存结果见仓库 tests 目录；逐页预览和生成工具检查不能代替桌面 PowerPoint 测试。桌面 PowerPoint 的实际编辑、保存和重开尚未实测。</p><p>事实及完整来源位于 working/evidence-ledger.json，PPT 备注和 HTML Sources 保留逐条来源位置。早期三页样张保留为风格参考快照，其旧资料状态不代表本版最新证据。</p></html>''',encoding='utf-8')
print('Wrote review-notes.html')
